#include "resident/domains/military/military_model.hpp"
// 仅原完整军事接敌来源先验后的窄读，不重新授权部队、不创造第二接敌账。
#include "military_field_terrain_source.hpp"
#include "military_field_terrain.hpp"
#include "resident/model/common_model.hpp"
namespace hanmo::resident {
namespace {template<class T>const T* find(const std::vector<T>& rows,const StableId& id){for(const auto& r:rows)if(r.id==id)return &r;return nullptr;}}
Status validate_military_field_contact_source(const MilitaryState& state,const MilitaryCatalog& catalog,const MilitaryContactFact& contact){if(!catalog.field_terrain_policy||contact.siege_id||contact.node_id)return common_success();const auto* actual=find(catalog.battle_catalog.battlefields,contact.battlefield_id);if(!contact.motion_sources)return actual&&actual->field_terrain?common_failure("MilitaryFieldTerrainActualContactRequired",contact.id):common_success();StableId aggressor;for(const auto& side:contact.side_by_army)if(side.second==0){if(!aggressor.empty())return common_failure("MilitaryFieldTerrainAggressorAmbiguous",contact.id);aggressor=side.first;}StableId order;for(const auto& source:contact.army_order_ids)if(source.first==aggressor){if(!order.empty())return common_failure("MilitaryFieldTerrainOrderAmbiguous",contact.id);order=source.second;}const auto* campaign=find(state.campaigns,order);const auto* definition=campaign?find(catalog.orders,campaign->template_id):nullptr;const auto* target=definition?find(catalog.strongholds,definition->target_stronghold_id):nullptr;const auto* topology=target?find(catalog.siege_topologies,target->topology_id):nullptr;if(!campaign||campaign->army_id!=aggressor||!definition||definition->objective_kind!="occupy"||!topology)return common_failure("MilitaryFieldTerrainOriginalOrderRequired",contact.id);StableId approach;for(const auto& node:topology->nodes)if(node.id==topology->attacker_entry_id){if(!approach.empty())return common_failure("MilitaryFieldTerrainApproachAmbiguous",contact.id);approach=node.battlefield_id;}auto selected=select_military_field_contact_battlefield(*catalog.field_terrain_policy,approach);if(!selected.ok)return {false,{},selected.error};return selected.value==contact.battlefield_id?common_success():common_failure("MilitaryFieldTerrainContactMismatch",contact.id);}
}
